446| async function runInit(opts: { boot?: boolean; target?: string }): Promise<void> {
447|   const workspace = path.resolve(opts.target ?? process.cwd());
448|   console.log(chalk.bold.cyan("muse-ts init — NodeOS readiness"));
449|   console.log(`${chalk.dim("workspace:")} ${workspace}`);
450|   console.log(`${chalk.dim("termux:")} ${process.env.TERMUX_VERSION ?? "(not detected)"}  ${chalk.dim("prefix:")} ${process.env.PREFIX ?? "(unset)"}`);
451| 
452|   for (const tool of ["python3", "node", "sqlite3", "fd", "rg", "nodeos"]) {
453|     const found = checkBin(tool);
454|     console.log(`  ${found ? chalk.green("ok ") : chalk.red("miss")} ${tool}${found ? chalk.dim(` → ${found}`) : ""}`);
455|   }
456| 
457|   // NodeOS daemon ping (CWD-bound semantics live in the daemon itself).
458|   try {
459|     const r = spawnSync("nodeos", ["-c", "ping"], { encoding: "utf-8", cwd: workspace });
460|     const out = (r.stdout + r.stderr).trim().split("\n")[0] ?? "";
461|     console.log(`${chalk.dim("nodeos:")} ${out || "(no output)"}`);
462|     if (/Offline/i.test(out) && opts.boot) {
463|       console.log(chalk.dim("booting daemon: nohup nodeos -d > daemon.log 2>&1 &"));
464|       const logPath = path.join(workspace, "daemon.log");
465|       const logFd = fs.openSync(logPath, "a");
466|       const child = spawn("nodeos", ["-d"], {
467|         cwd: workspace,
468|         detached: true,
469|         stdio: ["ignore", logFd, logFd],
470|       });
471|       child.unref();
472|       console.log(chalk.green(`daemon boot requested → ${logPath}`));
473|     }
474|   } catch (err) {
475|     console.log(`${chalk.dim("nodeos:")} ${chalk.red((err as Error).message)}`);
476|   }
477| 
478|   // hooks.json + workflow.json (CWD-relative).
479|   for (const rel of [".agents/hooks.json", "workflow.json"]) {
480|     const abs = path.join(workspace, rel);
481|     if (!fs.existsSync(abs)) {
482|       console.log(`  ${chalk.yellow("absent")} ${rel}`);
483|       continue;
484|     }
485|     try {
486|       JSON.parse(fs.readFileSync(abs, "utf-8"));
487|       console.log(`  ${chalk.green("ok ")} ${rel}`);
488|     } catch {
489|

489|       console.log(`  ${chalk.red("bad json")} ${rel}`);
490|     }
491|   }
492| 
493|   // agy_nodeos.db quick probe.
494|   const dbPath = path.join(workspace, "agy_nodeos.db");
495|   if (fs.existsSync(dbPath)) {
496|     try {
497|       const r = spawnSync(
498|         "python3",
499|         [
500|           "-c",
501|           `import sqlite3; c=sqlite3.connect(${JSON.stringify(dbPath)}).cursor(); c.execute('SELECT count(*) FROM nodes'); print(c.fetchone()[0])`,
502|         ],
503|         { encoding: "utf-8" },
504|       );
505|       console.log(`${chalk.dim("graph:")} ${r.status === 0 ? `${r.stdout.trim()} nodes` : chalk.yellow("unreadable")}`);
506|     } catch {
507|       console.log(`${chalk.dim("graph:")} ${chalk.yellow("probe failed")}`);
508|     }
509|   } else {
510|     console.log(`${chalk.dim("graph:")} ${chalk.yellow("no agy_nodeos.db in this CWD (dynamic binding — expected outside indexed roots)")}`);
511|   }
512| 
513|   // QA analyzer smoke (best-effort, offline).
514|   const qaScript = path.join(os.homedir(), ".gemini", "config", "skills", "qa-analyzer", "scripts", "analyzer.py");
515|   if (fs.existsSync(qaScript)) {
516|     const r = spawnSync("python3", [qaScript, workspace], { encoding: "utf-8" });
517|     console.log(`${chalk.dim("qa:")} ${r.status === 0 ? chalk.green("pass") : chalk.yellow("see output")}`);
518|     if (r.stdout.trim()) console.log(chalk.dim(r.stdout.trim().split("\n").slice(0, 10).join("\n")));
519|   } else {
520|     console.log(`${chalk.dim("qa:")} ${chalk.yellow("analyzer not installed — skipping")}`);
521|   }
522|   console.log(chalk.green("ready."));
523| }
