526| // CLI definition (commander)
527| // ---------------------------------------------------------------------------
528| 
529| function parseApproval(v: string): ApprovalMode {
530|   if (v === "untrusted" || v === "on-request" || v === "never") return v;
531|   throw new Error(`invalid approval mode: ${v}`);
532| }
533| 
534| function parseEffort(v: string): ReasoningEffort {
535|   const levels = ["none", "minimal", "low", "medium", "high", "xhigh", "max", "ultra"];
536|   if ((levels as string[]).includes(v)) return v as ReasoningEffort;
537|   throw new Error(`invalid reasoning effort: ${v}`);
538| }
