166| 
167| export class MetaChatClient {
168|   readonly baseUrl: string;
169|   readonly model: string;
170|   readonly reasoningEffort: ReasoningEffort;
171|   readonly parallelToolCalls: boolean;
172|   private token: string;
173|   readonly provider: "meta" | "echo" | "local";
174| 
175|   constructor(opts: {
176|     token: string;
177|     baseUrl?: string;
178|     model?: string;
179|     reasoningEffort?: ReasoningEffort;
180|     parallelToolCalls?: boolean;
181|     provider?: "meta" | "echo" | "local";
182|   }) {
183|     this.token = opts.token;
184|     this.baseUrl = (opts.baseUrl ?? DEFAULT_API_BASE_URL).replace(/\/+$/, "");
185|     this.model = opts.model ?? "muse-spark-1.3";
186|     this.reasoningEffort = opts.reasoningEffort ?? "high";
187|     this.parallelToolCalls = opts.parallelToolCalls ?? false;
188|     this.provider = opts.provider ?? "meta";
189|   }
190| 
191|   setToken(token: string): void {
192|     this.token = token;
193|   }
194| 
195|   async listModels(): Promise<string[]> {
196|     if (this.provider !== "meta") return [this.model];
197|     const res = await fetch(`${this.baseUrl}/models`, {
198|       headers: { authorization: `Bearer ${this.token}`, accept: "application/json" },
199|     });
200|     if (!res.ok) throw new Error(`model list failed: HTTP ${res.status}`);

200|     if (!res.ok) throw new Error(`model list failed: HTTP ${res.status}`);
201|     const data = (await res.json()) as { data?: { id?: string }[]; models?: string[] };
202|     if (Array.isArray(data.data)) {
203|       return data.data.map((m) => m.id ?? "").filter(Boolean);
204|     }
205|     if (Array.isArray(data.models)) return data.models;
206|     return [this.model];
207|   }
208| 
209|   private buildBody(
210|     messages: ChatMessage[],
211|     tools: ToolDefinition[],
212|     stream: boolean,
213|   ): Record<string, unknown> {
214|     const body: Record<string, unknown> = {
215|       model: this.model,
216|       messages: messages.map((m) => {
217|         const out: Record<string, unknown> = { role: m.role, content: m.content };
218|         if (m.name) out.name = m.name;
219|         if (m.tool_call_id) out.tool_call_id = m.tool_call_id;
220|         if (m.tool_calls) out.tool_calls = m.tool_calls;
221|         return out;
222|       }),
223|       stream,
224|     };
225|     // Meta-specific extensions (ignored by strict OpenAI servers).
226|     (body as Record<string, unknown>).reasoning_effort = this.reasoningEffort;
227|     (body as Record<string, unknown>).parallel_tool_calls = this.parallelToolCalls;
228|     if (tools.length > 0) body.tools = tools;
229|     return body;
230|   }
231| 
232|   /** Non-streaming single turn. Returns assistant message. */
233|   async chatOnce(messages: ChatMessage[], tools: ToolDefinition[]): Promise<ChatMessage> {
234|     if (this.provider === "echo" || this.provider === "local") {
235|       const last = [...messages].reverse().find((m) => m.role === "user");
236|       return {
237|         role: "assistant",
238|         content: `[${this.provider} provider — no network]\necho: ${last?.content ?? "(empty)"}`,
239|       };
240|     }
241|     const res = await fetch(`${this.baseUrl}/chat/completions`, {
242|       method: "POST",
243|       headers: {
244|         authorization: `Bearer ${this.token}`,
245|         "content-type": "application/json",
246|         accept: "application/json",
247|       },
248|       body: JSON.stringify(this.buildBody(messages, tools, false)),
249|     });
250|     if (!res.ok) {
251|       const text = (await res.text()).slice(0, 1000);
252|       throw new Error(`Meta API error HTTP ${res.status}: ${text}`);
253|     }
254|     const data = (await res.json()) as {
255|       choices?: { message?: { content?: string; tool_calls?: ToolCall[] } }[];
256|     };
257|     const msg = data.choices?.[0]?.message;
258|     return {
259|       role: "assistant",
260|       content: msg?.content ?? "",
261|       ...(msg?.tool_calls ? { tool_calls: msg.tool_calls } : {}),
262|     };
263|   }
264| 
265|   /** Streaming turn. Yields text deltas; returns full message via `done()`. */
266|   async *chatStream(
267|     messages: ChatMessage[],
268|     tools: ToolDefinition[],
269|   ): AsyncGenerator<
270|     { type: "text"; delta: string } | { type: "tool_calls"; toolCalls: ToolCall[] },
271|     ChatMessage,
272|     void
273|   > {
274|     if (this.provider === "echo" || this.provider === "local") {
275|       const last = [...messages].reverse().find((m) => m.role === "user");
276|       const content = `[${this.provider} provider — no network]\necho: ${last?.content ?? "(empty)"}`;
277|       yield { type: "text", delta: content };
278|       return { role: "assistant", content };
279|     }
280|     const res = await fetch(`${this.baseUrl}/chat/completions`, {
281|       method: "POST",
282|       headers: {
283|         authorization: `Bearer ${this.token}`,
284|         "content-type": "application/json",
285|         accept: "text/event-stream",
286|       },
287|       body: JSON.stringify(this.buildBody(messages, tools, true)),
288|     });
289|     if (!res.ok || !res.body) {
290|       // Fallback: some deployments ignore stream=true and return JSON.
291|       if (res.ok) {
292|         try {
293|           const data = (await res.json()) as {
294|             choices?: { message?: { content?: string; tool_calls?: ToolCall[] } }[];
295|           };
296|           const msg = data.choices?.[0]?.message;
297|           const content = msg?.content ?? "";
298|           if (content) yield { type: "text", delta: content };
299|           const full: ChatMessage = {
300|             role: "assistant",
301|             content,
302|             ...(msg?.tool_calls ? { tool_calls: msg.tool_calls } : {}),
303|           };
304|           if (full.tool_calls) yield { type: "tool_calls", toolCalls: full.tool_calls };
305|           return full;
306|         } catch {
307|           /* fall through to error */
308|         }
309|       }
310|       const text = await res.text().catch(() => "").then((t) => t.slice(0, 1000));
311|       throw new Error(`Meta API stream error HTTP ${res.status}: ${text}`);
312|     }
313|     const reader = res.body.getReader();
314|     const decoder = new TextDecoder();
315|     let buffer = "";
316|     let content = "";
317|     const toolCallParts = new Map<number, { id: string; name: string; args: string }>();
318| 
319|     const flushBlock = function* (
320|       block: string,
321|     ): Generator<{ type: "text"; delta: string }> {
322|       for (const line of block.split("\n")) {
323|         const trimmed = line.trim();
324|         if (!trimmed.startsWith("data:")) continue;
325|         const payload = trimmed.slice(5).trim();
326|         if (payload === "[DONE]") continue;
327|         try {
328|           const evt = JSON.parse(payload) as {
329|             choices?: {
330|               delta?: {
331|                 content?: string;
332|                 tool_calls?: {
333|                   index?: number;
334|                   id?: string;
335|                   function?: { name?: string; arguments?: string };
336|                 }[];
337|               };
338|             }[];
339|           };
340|           const delta = evt.choices?.[0]?.delta;
341|           if (typeof delta?.content === "string" && delta.content.length > 0) {
342|             content += delta.content;
343|             yield { type: "text", delta: delta.content };
344|           }
345|           for (const tc of delta?.tool_calls ?? []) {
346|             const idx = tc.index ?? 0;
347|             const prev = toolCallParts.get(idx) ?? { id: "", name: "", args: "" };
348|             if (tc.id) prev.id = tc.id;
349|             if (tc.function?.name) prev.name = tc.function.name;
350|             if (tc.function?.arguments) prev.args += tc.function.arguments;
351|             toolCallParts.set(idx, prev);
352|           }
353|         } catch {
354|           continue;
355|         }
356|       }
357|     };
358| 
359|     while (true) {
360|       const { done, value } = await reader.read();
361|       if (done) break;
362|       buffer += decoder.decode(value, { stream: true });
363|       let sep: number;
364|       while ((sep = buffer.indexOf("\n\n")) !== -1) {
365|         const block = buffer.slice(0, sep);
366|         buffer = buffer.slice(sep + 2);
367|         yield* flushBlock(block);
368|       }
369|     }
370|     buffer += decoder.decode();
371|     if (buffer.trim().length > 0) yield* flushBlock(buffer);
372| 
373|     const toolCalls: ToolCall[] = [...toolCallParts.entries()]
374|       .sort((a, b) => a[0] - b[0])
375|       .filter(([, p]) => p.name.length > 0)
376|       .map(([, p], i) => ({
377|         id: p.id || `call_${i}`,
378|         type: "function" as const,
379|         function: { name: p.name, arguments: p.args || "{}" },
380|       }));
381|     const full: ChatMessage = {
382|       role: "assistant",
383|       content,
384|       ...(toolCalls.length > 0 ? { tool_calls: toolCalls } : {}),
385|     };
386|     if (toolCalls.length > 0) yield { type: "tool_calls", toolCalls };
387|     return full;
388|   }
389| }
