391| // ---------------------------------------------------------------------------
392| // Workspace tools (scoped to workspace root, approval-gated)
393| // ---------------------------------------------------------------------------
394| 
395| export class WorkspaceTools {
396|   readonly root: string;
397|   approvalMode: ApprovalMode;
398| 
399|   constructor(root: string, approvalMode: ApprovalMode = "on-request") {
400|     this.root = path.resolve(root);
401|     this.approvalMode = approvalMode;
402|   }
403| 
404|   resolve(p: string): string {
405|     const abs = path.isAbsolute(p) ? path.normalize(p) : path.resolve(this.root, p);
406|     const rel = path.relative(this.root, abs);
407|     if (rel.startsWith("..") || path.isAbsolute(rel)) {
408|       throw new Error(`path escapes workspace root: ${p}`);
409|     }
410|     return abs;
411|   }
412| 
413|   async approve(action: string, detail: string): Promise<boolean> {
414|     if (this.approvalMode === "never") return true;
415|     if (this.approvalMode === "untrusted") return false;
416|     try {
417|       const { ok } = await inquirer.prompt<{ ok: boolean }>([
418|         {
419|           type: "confirm",
420|           name: "ok",
421|           message: `${action} ${detail} ?`,
422|           default: false,
423|         },
424|       ]);
425|       return ok;
426|     } catch {
427|       return false;
428|     }
429|   }
430| 
431|   readFile(p: string, offset = 1, limit = 200): string {
432|     const abs = this.resolve(p);
433|     const raw = fs.readFileSync(abs, "utf-8");
434|     const lines = raw.split("\n");
435|     const start = Math.max(1, offset);
436|     const slice = lines.slice(start - 1, start - 1 + Math.min(Math.max(1, limit), 2000));
437|     const numbered = slice.map((ln, i) => `${String(start + i).padStart(5)}| ${ln}`);
438|     return numbered.join("\n");
439|   }
440| 
441|   writeFile(p: string, content: string): string {
442|     const abs = this.resolve(p);
443|     fs.mkdirSync(path.dirname(abs), { recursive: true });
444|     fs.writeFileSync(abs, content, "utf-8");
445|     return `wrote ${content.length} bytes to ${path.relative(this.root, abs) || abs}`;
446|   }
447| 
448|   listDir(p = "."): string {
449|     const abs = this.resolve(p);
450|     const entries = fs.readdirSync(abs, { withFileTypes: true });
451|     return entries
452|       .map((e) => `${e.isDirectory() ? "dir " : "file"} ${e.name}`)
453|       .join("\n");
454|   }
455| 
456|   bash(command: string, timeoutMs = 10_000): Promise<{ stdout: string; stderr: string; exitCode: number }> {
457|     return new Promise((resolve) => {
458|       const child = spawn(command, {
459|         shell: process.env.SHELL ?? "/bin/sh",
460|         cwd: this.root,
461|         timeout: Math.min(Math.max(1000, timeoutMs), 120_000),
462|       });
463|       let stdout = "";
464|       let stderr = "";
465|       child.stdout.on("data", (d) => {
466|         stdout += String(d);
467|         if (stdout.length > 200_000) stdout = stdout.slice(-200_000);
468|       });
469|       child.stderr.on("data", (d) => {
470|         stderr += String(d);
471|         if (stderr.length > 200_000) stderr = stderr.slice(-200_000);
472|       });
473|       child.on("close", (code) => resolve({ stdout, stderr, exitCode: code ?? -1 }));
474|       child.on("error", (err) => resolve({ stdout, stderr: String(err), exitCode: -1 }));
475|     });
476|   }
477| 
478|   /** Scoped literal search. Skips .git/node_modules; caps files + matches. */
479|   search(pattern: string, dir = ".", maxMatches = 50): string {
480|     const abs = this.resolve(dir);
481|     const results: string[] = [];
482|     const skip = new Set([".git", "node_modules", ".muse"]);
483|     const stack: string[] = [abs];
484|     let filesScanned = 0;
485|     while (stack.length > 0 && results.length < maxMatches && filesScanned < 2000) {
486|       const cur = stack.pop() as string;
487|       let entries: fs.Dirent[];
488|       try {
489|         entries = fs.readdirSync(cur, { withFileTypes: true });
490|       } catch {
491|         continue;
492|       }
493|       for (const e of entries) {
494|         if (results.length >= maxMatches) break;
495|         if (skip.has(e.name)) continue;
496|         const full = path.join(cur, e.name);
497|         if (e.isDirectory()) {
498|           stack.push(full);
499|         } else if (e.isFile()) {
500|           filesScanned++;
501|           let text: string;
502|           try {
503|             const stat = fs.statSync(full);
504|             if (stat.size > 512 * 1024) continue;
505|             text = fs.readFileSync(full, "utf-8");
506|           } catch {
507|             continue;
508|           }
509|           const lines = text.split("\n");
510|           for (let i = 0; i < lines.length && results.length < maxMatches; i++) {
511|             if (lines[i].includes(pattern)) {
512|               const rel = path.relative(this.root, full);
513|               results.push(`${rel}:${i + 1}: ${lines[i].slice(0, 300)}`);
514|             }
515|           }
516|         }
517|       }
518|     }
519|     return results.length > 0
520|       ? results.join("\n")
521|       : `(no matches for ${JSON.stringify(pattern)} in ${dir})`;
522|   }
523| 
524|   /** Execute one model tool call. Returns text for the tool result message. */
525|   async executeToolCall(
526|     call: ToolCall,
527|     opts: { autoApprove?: boolean } = {},
528|   ): Promise<string> {
529|     const name = call.function.name;
530|     let args: Record<string, unknown> = {};
531|     try {
532|       args = JSON.parse(call.function.arguments || "{}") as Record<string, unknown>;
533|     } catch {
534|       return `error: invalid JSON arguments: ${call.function.arguments.slice(0, 300)}`;
535|     }
536|     const str = (v: unknown, fallback = ""): string =>
537|       typeof v === "string" ? v : fallback;
538|     const num = (v: unknown, fallback: number): number =>
539|       typeof v === "number" && Number.isFinite(v) ? v : fallback;
540| 
541|     switch (name) {
542|       case "read_file": {
543|         const p = str(args.path);
544|         if (!p) return "error: read_file requires `path`";
545|         try {
546|           return this.readFile(p, num(args.offset, 1), num(args.limit, 200));
547|         } catch (err) {
548|           return `error: ${(err as Error).message}`;
549|         }
550|       }
551|       case "list_dir": {
552|         try {
553|           return this.listDir(str(args.path, "."));
554|         } catch (err) {
555|           return `error: ${(err as Error).message}`;
556|         }
557|       }
558|       case "search": {
559|         const pattern = str(args.pattern);
560|         if (!pattern) return "error: search requires `pattern`";
561|         return this.search(pattern, str(args.dir, "."), num(args.max_matches, 50));
562|       }
563|       case "write_file": {
564|         const p = str(args.path);
565|         const content = typeof args.content === "string" ? args.content : null;
566|         if (!p || content === null) return "error: write_file requires `path` + `content`";
567|         const ok =
568|           opts.autoApprove || this.approvalMode === "never"
569|             ? true
570|             : await this.approve("write_file", p);
571|         if (!ok) return "denied by approval policy";
572|         try {
573|           return this.writeFile(p, content);
574|         } catch (err) {
575|           return `error: ${(err as Error).message}`;
576|         }
577|       }
578|       case "bash": {
579|         const command = str(args.command);
580|         if (!command) return "error: bash requires `command`";
581|         const ok =
582|           opts.autoApprove || this.approvalMode === "never"
583|             ? true
584|             : await this.approve("bash", command.slice(0, 120));
585|         if (!ok) return "denied by approval policy";
586|         const r = await this.bash(command, num(args.timeout_ms, 10_000));
587|         const head = `exit=${r.exitCode}`;
588|         const out = [
589|           head,
590|           r.stdout.trim() ? `--- stdout ---\n${r.stdout.slice(-8000)}` : "(no stdout)",
591|           r.stderr.trim() ? `--- stderr ---\n${r.stderr.slice(-4000)}` : "",
592|         ]
593|           .filter(Boolean)
594|           .join("\n");
595|         return out;
596|       }
597|       default:
598|         return `error: unknown tool: ${name}`;
599|     }
600|   }
601| }
