605| // ---------------------------------------------------------------------------
606| 
607| export function createSession(workspace: string, sessionId?: string): SessionInfo {
608|   const id = sessionId ?? randomUUID();
609|   const now = new Date();
610|   const yyyy = String(now.getFullYear());
611|   const mm = String(now.getMonth() + 1).padStart(2, "0");
612|   const dd = String(now.getDate()).padStart(2, "0");
613|   const dir = path.join(workspace, ".muse", "sessions", yyyy, mm, dd, id);
614|   return { sessionId: id, sessionDir: dir, sessionFile: path.join(dir, "session.jsonl"), workspace };
615| }
616| 
617| export function appendSessionLine(
618|   session: SessionInfo,
619|   record: Record<string, unknown>,
620|   noLog = false,
621| ): void {
622|   if (noLog || !session.sessionFile) return;
623|   try {
624|     fs.mkdirSync(session.sessionDir, { recursive: true });
625|     fs.appendFileSync(session.sessionFile, JSON.stringify(record) + "\n", "utf-8");
626|   } catch {
627|     /* session logging must never crash the TUI */
628|   }
629| }
630| 
631| /** Best-effort mirror into the Rust-shared XDG history. */
632| export function appendXdgHistory(text: string): void {
633|   try {
634|     const dir = path.join(os.homedir(), ".local", "share", "muse");
635|     fs.mkdirSync(dir, { recursive: true });
636|     fs.appendFileSync(
637|       path.join(dir, "tui-history.jsonl"),
638|       JSON.stringify(text) + "\n",
639|       "utf-8",
640|     );
641|   } catch {
642|     /* ignore */
643|   }
644| }
645| 
646| function readWorkflowPending(workspace: string): string | null {
647|   try {
648|     const raw = fs.readFileSync(path.join(workspace, "workflow.json"), "utf-8");
649|     const data = JSON.parse(raw) as { status?: string; intent?: string; task?: string };
650|     if (data && typeof data === "object") {
651|       const status = String(data.status ?? "unknown");
652|       if (status === "pending" || status === "running") {
653|         return `${status}: ${String(data.intent ?? data.task ?? "").slice(0, 160)}`;
654|       }
655|       return `status=${status}`;
656|     }
657|   } catch {
658|     /* no workflow.json in this CWD — fine (dynamic binding) */
659|   }
660|   return null;
661| }
