 705| /** Minimal markdown-ish render: code fences dimmed, headers bold. */
 706| export function renderAssistant(text: string): string {
 707|   const lines = text.split("\n");
 708|   let inFence = false;
 709|   return lines
 710|     .map((ln) => {
 711|       if (ln.trimStart().startsWith("```")) {
 712|         inFence = !inFence;
 713|         return chalk.dim(ln);
 714|       }
 715|       if (inFence) return chalk.dim(ln);
 716|       if (/^#{1,4}\s/.test(ln)) return chalk.bold.white(ln);
 717|       return ln;
 718|     })
 719|     .join("\n");
