 725| 
 726| export async function runTui(opts: TuiOptions = {}): Promise<void> {
 727|   const workspace = path.resolve(opts.workspace ?? process.cwd());
 728|   const approvalMode: ApprovalMode = opts.approvalMode ?? "on-request";
 729|   const provider = opts.provider ?? "meta";
 730|   let model = opts.model ?? "muse-spark-1.3";
 731|   let effort: ReasoningEffort = opts.reasoningEffort ?? "high";
 732| 
 733|   // Resolve credentials (env wins).
 734|   let resolved = resolveCredential();
 735|   let baseUrl = opts.baseUrl ?? resolved?.baseUrl ?? DEFAULT_API_BASE_URL;
 736|   if (provider === "meta" && !resolved) {
 737|     console.log(
 738|       chalk.yellow("Not logged in."),
 739|       "Run",
 740|       chalk.cyan("/login"),
 741|       "or set META_API_KEY. Starting in echo mode for now.",
 742|     );
 743|   }
 744|   const effectiveProvider = provider === "meta" && !resolved ? "echo" : provider;
 745| 
 746|   const client = new MetaChatClient({
 747|     token: resolved?.token ?? "unset",
 748|     baseUrl,
 749|     model,
 750|     reasoningEffort: effort,
 751|     parallelToolCalls: opts.parallelToolCalls ?? false,
 752|     provider: effectiveProvider,
 753|   });
 754|   const tools = new WorkspaceTools(workspace, approvalMode);
 755|   const session = createSession(workspace, opts.sessionId);
 756|   const noLog = opts.noSessionLog ?? false;
 757|   if (!noLog && session.sessionFile) {
 758|     try {
 759|       fs.mkdirSync(session.sessionDir, { recursive: true });
 760|     } catch {
 761|       /* ignore */
 762|     }
 763|   }
 764| 
 765|   console.log(
 766|     banner({
 767|       model: client.model,
 768|       effort: client.reasoningEffort,
 769|       workspace,
 770|       sessionId: session.sessionId,
 771|       approval: tools.approvalMode,
 772|       provider: client.provider,
 773|     }),
 774|   );
 775|   const pending = readWorkflowPending(workspace);
 776|   if (pending) {
 777|     console.log(chalk.dim(`workflow.json: ${pending}`));
 778|   }
 779|   appendSessionLine(session, {
 780|     type: "session_open",
 781|     ts: new Date().toISOString(),
 782|     model,
 783|     reasoning_effort: effort,
 784|     workspace,
 785|     provider: client.provider,
 786|   }, noLog);
 787| 
 788|   const history: ChatMessage[] = [
 789|     {
 790|       role: "system",
 791|       content:
 792|         "You are muse-ts, a terminal coding assistant. Be direct, technical, and precise. " +
 793|         "Use workspace tools (read_file, write_file, list_dir, bash, search) to inspect and edit code. " +
 794|         "Scope every search to explicit directories; never scan the whole filesystem. " +
 795|         "Explain plans briefly before running mutating commands.",
 796|     },
 797|   ];
 798| 
 799|   let queuedInitial: string | null = opts.initialPrompt ?? null;
 800| 
 801|   while (true) {
 802|     let userText: string;
 803|     if (queuedInitial !== null) {
 804|       userText = queuedInitial;
 805|       queuedInitial = null;
 806|       console.log(chalk.bold.magenta("› ") + userText);
 807|     } else {
 808|       try {
 809|         const answer = await inquirer.prompt<{ q: string }>([
 810|           {
 811|             type: "input",
 812|             name: "q",
 813|             message: chalk.bold.magenta("›"),
 814|             prefix: "",
 815|           },
 816|         ]);
 817|         userText = (answer.q ?? "").trim();
 818|       } catch {
 819|         console.log(chalk.dim("\nbye."));
 820|         break;
 821|       }
 822|     }
 823|     if (!userText) continue;
 824|     appendXdgHistory(userText);
 825| 
 826|     // ---- slash commands ----
 827|     if (userText.startsWith("/")) {
 828|       const [cmd, ...rest] = userText.slice(1).split(/\s+/);
 829|       const arg = rest.join(" ").trim();
 830|       const command = cmd.toLowerCase();
 831|       if (command === "exit" || command === "quit") {
 832|         console.log(chalk.dim("bye."));
 833|         break;
 834|       } else if (command === "help") {
 835|         console.log(helpText());
 836|         continue;
 837|       } else if (command === "status") {
 838|         resolved = resolveCredential();
 839|         console.log(
 840|           [
 841|             `${chalk.dim("auth:")} ${resolved ? `${chalk.green("logged in")} via ${resolved.source}` : chalk.red("logged out")}`,
 842|             `${chalk.dim("base:")} ${baseUrl}`,
 843|             `${chalk.dim("model:")} ${client.model}  ${chalk.dim("effort:")} ${client.reasoningEffort}`,
 844|             `${chalk.dim("session:")} ${session.sessionId}`,
 845|             `${chalk.dim("context:")} ${history.length} messages`,
 846|           ].join("\n"),
 847|         );
 848|         continue;
 849|       } else if (command === "clear") {
 850|         history.splice(1);
 851|         console.log(chalk.dim("context cleared."));
 852|         continue;
 853|       } else if (command === "model") {
 854|         if (!arg) {
 855|           console.log(`model: ${chalk.green(client.model)}`);
 856|           try {
 857|             const models = await client.listModels();
 858|             console.log(chalk.dim(models.slice(0, 20).join(", ")));
 859|           } catch (err) {
 860|             console.log(chalk.dim(`(model list unavailable: ${(err as Error).message})`));
 861|           }
 862|         } else {
